import os
import json

frozen_base = "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen"
demo_candidates = []

for root, dirs, files in os.walk(frozen_base):
    for f in files:
        if f.endswith('.json'):
            full = os.path.join(root, f)
            try:
                with open(full) as fh:
                    data = json.load(fh)
                if isinstance(data, (dict, list)):
                    if isinstance(data, dict) and 'input' in data:
                        demo_candidates.append((full, data))
            except:
                continue

print(f"Found {len(demo_candidates)} files with 'input' field")
for path, data in demo_candidates[:5]:
    print(f"\n{path}")
    if isinstance(data, dict) and 'input' in data:
        inp = data['input']
        out = data.get('output', 'N/A')
        print(f"  INPUT type: {type(inp)}")
        print(f"  OUTPUT type: {type(out)}")
        if isinstance(inp, list):
            print(f"  Input sample: {inp[:3]}")

